// Patrones para textos que mezclan contenido propio (motivo de la incidencia, tren, estaciones)
// con texto de la interfaz: [expresión regular sobre el texto completo, català, English].
window.I18N_PATTERNS = [
  [/^Se salta de las (\S+) al final de la jornada y se muestra el balance\. La simulación ya está calculada entera, así que los resultados son los mismos que viéndola hasta el final\.$/, "Se salta de les $1 al final de la jornada i es mostra el balanç. La simulació ja està calculada sencera, així que els resultats són els mateixos que mirant-la fins al final.", "Jumps from $1 to the end of the day and shows the summary. The simulation is already fully computed, so the results are the same as watching it to the end."],
  [/^Cadenciado · (.+)$/, "Cadenciat · $1", "Clock-face · $1"],
  [/^(\d+) marcador(es)? · guardado el (.+)$/, "$1 marcador$2 · desat el $3", "$1 marker(s) · saved on $3"],
  [/^→ (.+) \(final\)$/, "→ $1 (final)", "→ $1 (terminus)"],
  [/^(.+) · Señal roja \((\d+) sentido\)$/, "$1 · Senyal vermell ($2 sentit)", "$1 · Red signal ($2 direction)"],
  [/^(.+) · Señal roja \((\d+) sentidos\)$/, "$1 · Senyal vermell ($2 sentits)", "$1 · Red signal ($2 directions)"],
  [/^(.+) · Tramo → vía única$/, "$1 · Tram → via única", "$1 · Section → single track"],
  [/^(.+) \((\d+) servicios\)$/, "$1 ($2 serveis)", "$1 ($2 services)"],
  [/^en (.+ → .+)$/, "a $1", "on $1"],
  [/^Tren (\S+) \((\S+)\)$/, "Tren $1 ($2)", "Train $1 ($2)"],
  [/^Autobús (\S+) \((\S+)\) · sustitución$/, "Autobús $1 ($2) · substitució", "Bus $1 ($2) · replacement"],
  [/^Avaria de senyalització \((\d+) sentits?\) · (.+)$/, null, "Signal failure ($1 direction(s)) · $2"],
  [/^Bloqueig de cantó \((\d+) sentits?\) · (.+)$/, null, "Block closure ($1 direction(s)) · $2"],
  [/^Escenario: bloqueo del cantón (.+) a les (\S+)\. Cada fila es una duración de bloqueo \(Monte Carlo, rayon · motor unificado\)\.$/, "Escenari: bloqueig del cantó $1 a les $2. Cada fila és una durada de bloqueig (Monte Carlo, rayon · motor unificat).", "Scenario: closure of block section $1 at $2. Each row is a closure duration (Monte Carlo, rayon · unified engine)."],
];
